// func compressChunks8AVX512(cvs *[8][8]uint32, buf *byte, n uint64, key *[8]uint32, counter uint64, flags uint32)
// Requires: AVX, AVX2, AVX512F, AVX512VL
TEXT ·compressChunks8AVX512(SB), NOSPLIT, $160-44
	MOVQ cvs+0(FP), AX
	MOVQ buf+8(FP), CX
	MOVQ n+16(FP), DX
	MOVQ key+24(FP), BX
	MOVQ counter+32(FP), SI
	MOVL flags+40(FP), DI

	// Locate each lane's chunk
	DECQ         DX
	VPBROADCASTD DX, Y8
	VPMINUD      seq<>+0(SB), Y8, Y8
	VPSLLD       $0x0a, Y8, Y8
	VMOVDQU32    Y8, (SP)

	// Initialize counter
	VPBROADCASTD SI, Y8
	VPADDD       seq<>+0(SB), Y8, Y8
	VPCMPUD      $0x01, seq<>+0(SB), Y8, K1
	SHRQ         $0x20, SI
	VPBROADCASTD SI, Y9
	VPADDD.BCST  seq<>+4(SB), Y9, K1, Y9
	VMOVDQU32    Y8, 32(SP)
	VMOVDQU32    Y9, 64(SP)

	// Initialize flags
	MOVL DI, 96(SP)
	MOVL DI, 100(SP)
	MOVL DI, 104(SP)
	MOVL DI, 108(SP)
	MOVL DI, 112(SP)
	MOVL DI, 116(SP)
	MOVL DI, 120(SP)
	MOVL DI, 124(SP)
	MOVL DI, 128(SP)
	MOVL DI, 132(SP)
	MOVL DI, 136(SP)
	MOVL DI, 140(SP)
	MOVL DI, 144(SP)
	MOVL DI, 148(SP)
	MOVL DI, 152(SP)
	MOVL DI, 156(SP)
	ORL  $0x01, 96(SP)
	ORL  $0x02, 156(SP)

	// Load key
	VPBROADCASTD (BX), Y0
	VPBROADCASTD 4(BX), Y1
	VPBROADCASTD 8(BX), Y2
	VPBROADCASTD 12(BX), Y3
	VPBROADCASTD 16(BX), Y4
	VPBROADCASTD 20(BX), Y5
	VPBROADCASTD 24(BX), Y6
	VPBROADCASTD 28(BX), Y7

	// Loop index
	XORQ DX, DX

loop:
	// Load transposed block
	MOVL         (SP), BX
	MOVL         16(SP), SI
	VMOVDQU32    (CX)(BX*1), X8
	VINSERTI32X4 $0x01, (CX)(SI*1), Y8, Y8
	MOVL         4(SP), BX
	MOVL         20(SP), SI
	VMOVDQU32    (CX)(BX*1), X9
	VINSERTI32X4 $0x01, (CX)(SI*1), Y9, Y9
	MOVL         8(SP), BX
	MOVL         24(SP), SI
	VMOVDQU32    (CX)(BX*1), X10
	VINSERTI32X4 $0x01, (CX)(SI*1), Y10, Y10
	MOVL         12(SP), BX
	MOVL         28(SP), SI
	VMOVDQU32    (CX)(BX*1), X11
	VINSERTI32X4 $0x01, (CX)(SI*1), Y11, Y11
	VPUNPCKLQDQ  Y9, Y8, Y12
	VPUNPCKHQDQ  Y9, Y8, Y13
	VPUNPCKLQDQ  Y11, Y10, Y14
	VPUNPCKHQDQ  Y11, Y10, Y15
